INSERT INTO projection.claims ("release_root", "repository_id", "claim_id", "claim_root", "standing", "assertion", "assertion_kind", "conditions", "created_at", "source_title", "source_type", "evidence_count", "imported_object_id", "imported_object_root", "contested", "retracted", "source_path", "record", "row_root") VALUES ('sha256:53a7cedcf0df635437ff442498c15801b09399f6cc4441dc041d725bcb318476', '3d012325-3768-4b95-a385-c94e9f2a57a6', 'vcl_9ba852a45d8bc6f9dd024d85ff19e0b81317945f45e9eb073a89e44760a6b009', 'sha256:8e762a3a7dff021b90d15618d8197ed2454d457416a494ae57e90d2b00688fb4', 'superseded', 'At lean-proofs commit 423344341fbfdf4f8f684a302c5d05379125e7dc, Erdos94.variants.sum_multiplicity proves that for every finite planar point set P, the sum over its distinct determined distances of the unordered-pair distance multiplicities equals P.card.choose 2, matching Formal Conjectures commit 94a278e06a8bcbc2e4f2935e491c0c115ec832e0.', 'theoretical', '["Exact source, proof, target, toolchain, integration, and Method roots retained in evidence/current/erdos-94/pilot-input.v1.json.","Caveat: This proves only the elementary sum_multiplicity identity, not the cubic Erdős 94 theorem or either other variant.","Caveat: The Formal Conjectures build needs the mechanical Sym2.mk.uncurry to Sym2.mk API spelling change between its pinned Mathlib and lean-proofs.","Caveat: No external source-owner review, human review, upstream acceptance, or external adoption occurred.","Caveat: Producer checks are not Verification, Decision, or Standing."]'::jsonb, '2026-08-17T18:34:55.000Z', 'Authenticated Submission vsb_f43df4adcf653c88', 'submission', 2, NULL, NULL, FALSE, FALSE, 'records/claims/sha256/8e762a3a7dff021b90d15618d8197ed2454d457416a494ae57e90d2b00688fb4.json', '{"schema":"vela.claim-record.v1","claim_id":"vcl_9ba852a45d8bc6f9dd024d85ff19e0b81317945f45e9eb073a89e44760a6b009","evidence":[{"relation":"supports","artifact_path":"records/artifacts/sha256/e2054e7d5d57d1d1f4fd311d26dba65afb90ef873e7f04cb7bb5e431e43148eb","artifact_root":"sha256:e2054e7d5d57d1d1f4fd311d26dba65afb90ef873e7f04cb7bb5e431e43148eb"},{"relation":"supports","artifact_path":"records/artifacts/sha256/119e4d22c1e8e5f2931f576e6e1af92f906f7bd49d7f4de28b22cb92955600ad","artifact_root":"sha256:119e4d22c1e8e5f2931f576e6e1af92f906f7bd49d7f4de28b22cb92955600ad"}],"revision":1,"assertion":{"kind":"theoretical","text":"At lean-proofs commit 423344341fbfdf4f8f684a302c5d05379125e7dc, Erdos94.variants.sum_multiplicity proves that for every finite planar point set P, the sum over its distinct determined distances of the unordered-pair distance multiplicities equals P.card.choose 2, matching Formal Conjectures commit 94a278e06a8bcbc2e4f2935e491c0c115ec832e0."},"relations":[],"conditions":["Exact source, proof, target, toolchain, integration, and Method roots retained in evidence/current/erdos-94/pilot-input.v1.json.","Caveat: This proves only the elementary sum_multiplicity identity, not the cubic Erdős 94 theorem or either other variant.","Caveat: The Formal Conjectures build needs the mechanical Sym2.mk.uncurry to Sym2.mk API spelling change between its pinned Mathlib and lean-proofs.","Caveat: No external source-owner review, human review, upstream acceptance, or external adoption occurred.","Caveat: Producer checks are not Verification, Decision, or Standing."],"created_at":"2026-08-17T18:34:55Z","provenance":[{"kind":"submission","year":2026,"title":"Authenticated Submission vsb_f43df4adcf653c88","authors":["agent:submission-v3-migration"]}]}'::jsonb, 'sha256:0cb4bc05181fe40813627e00d945cec13212db3094e24775613f4f170567e738');
INSERT INTO projection.claims ("release_root", "repository_id", "claim_id", "claim_root", "standing", "assertion", "assertion_kind", "conditions", "created_at", "source_title", "source_type", "evidence_count", "imported_object_id", "imported_object_root", "contested", "retracted", "source_path", "record", "row_root") VALUES ('sha256:53a7cedcf0df635437ff442498c15801b09399f6cc4441dc041d725bcb318476', '3d012325-3768-4b95-a385-c94e9f2a57a6', 'vcl_b9c6915de55e15c69d06b9aeed786b0e632986374a347d77ff447ad244f67a2e', 'sha256:58f97ba8a90d23d4655c4b71051c6bdd4723c0454f31f4ed3cb3e95b0a6c8b15', 'accepted', 'At Formal Conjectures commit 59f30aa314ba225fcd9268723ce8291616df1ab0, the Lean development starfleet/erdos-321 establishes a two-sided asymptotic bound on extremalSize, which denotes the same quantity as Formal Conjectures'' Erdos321.R and therefore supplies a candidate answer for the exact occurrence Erdos321.erdos_321.variants.isTheta, not a proof of it. For occurrence resolution only, the exact occurrences Erdos321.erdos_321 and Erdos321.erdos_321.variants.isTheta are associated with problem:erdos:321 under resolver root sha256:a9d6787719c5c8069a9e14ade0f5a62975410272e6cd1583865b282d1d8669dd. At the exact retained Erdős 321 source revisions, the terminal theorem and structural comparison do not establish implication to either fixed Nat.log variant.', 'theoretical', '["Exact source revisions, occurrence resolver root, and retained evidence/current/erdos-321 inputs only.","Caveat: Erdos problem 321 remains open; this does not assert resolution or optimality.","Caveat: Occurrence association is navigation-only and establishes no statement equivalence.","Caveat: The negative comparison does not show that a bridge is impossible or that either statement is false.","Caveat: The retained terminal and fixed sources have no exact resolved joint Lean environment."]'::jsonb, '2026-08-17T18:33:12.000Z', 'Authenticated Submission vsb_a72e375d5b327714', 'submission', 1, NULL, NULL, FALS