INSERT INTO projection.reviews ("release_root", "repository_id", "proposal_id", "status", "kind", "target", "claim", "content_root", "receipt_root", "created_at", "reviewed_at", "reviewed_by", "decision_actor_class", "decision_session_ref", "decision_authority_principal_id", "decision_event_id", "decision_plan_root", "decision_provenance", "applied_event_id", "decision_reason", "decision_packet", "proposed_state_preview", "claim_retirement", "retired_by_claim_id", "row_root") VALUES ('sha256:c9d14c459c518937e758918b5897dc3b22f1a55f07739afe99502f5b046c907a', '3d012325-3768-4b95-a385-c94e9f2a57a6', 'vpr_2c3fe5888b00366a', 'accepted', 'claim.revise', 'vcl_b9c6915de55e15c69d06b9aeed786b0e632986374a347d77ff447ad244f67a2e', 'At Formal Conjectures commit 59f30aa314ba225fcd9268723ce8291616df1ab0, the Lean development starfleet/erdos-321 establishes a two-sided asymptotic bound on extremalSize, which denotes the same quantity as Formal Conjectures'' Erdos321.R and therefore supplies a candidate answer for the exact occurrence Erdos321.erdos_321.variants.isTheta, not a proof of it. For occurrence resolution only, the exact occurrences Erdos321.erdos_321 and Erdos321.erdos_321.variants.isTheta are associated with problem:erdos:321 under resolver root sha256:a9d6787719c5c8069a9e14ade0f5a62975410272e6cd1583865b282d1d8669dd. At the exact retained Erdős 321 source revisions, the terminal theorem and structural comparison do not establish implication to either fixed Nat.log variant.', 'sha256:58f97ba8a90d23d4655c4b71051c6bdd4723c0454f31f4ed3cb3e95b0a6c8b15', 'sha256:a72e375d5b327714edea3a4fca5397389ddbae68519ad46162d36773eefe18e1', '2026-08-17T18:33:14.000Z', '2026-08-17T18:33:47.000Z', 'agent:submission-v3-migration', 'agent', NULL, 'local:device-sha256:67fbb8e56377e6868e9f941524e0bf39cfb4fd2a4bfdd25c2edb93fc82f86213|uid:501', 'vev_15632b53fb7fd674', NULL, 'signed_record', 'vev_b1a3213862d0bd53', 'Accept the exact current Erdős 321 assertion in the compact v3 lineage after a scoped fidelity check; preserve the correction relation and limitations without changing the scientific content.', NULL, '{"base":{"git_commit":"552d14af7620e4e7021747ec79f57a306fcc002f","revision_root":"sha256:c7c30533b82f0ce710a6d60ee4c6717e688fe813ce124e4ced564a723f46bc53","repository_root":"sha256:6da29efeedc34fb6e505c7546e894390418c807342940ecbf60cc025f99ddc1c"},"state":"terminal_historical","inputs":{"claim_root":"sha256:58f97ba8a90d23d4655c4b71051c6bdd4723c0454f31f4ed3cb3e95b0a6c8b15","proposal_root":"sha256:2c3fe5888b00366ae66d638ada6511253311df9885474c48c3345d4adb45b730","repository_root":"sha256:6da29efeedc34fb6e505c7546e894390418c807342940ecbf60cc025f99ddc1c","submission_root":"sha256:a72e375d5b327714edea3a4fca5397389ddbae68519ad46162d36773eefe18e1","verification_set_root":"sha256:e1879c19e8c2c857508ba9aafdc77d4fd530f91cc589119ee996e9a34a8e13fe"},"schema":"vela.projection-proposed-state-preview.v1","blocker":null,"terminal":{"git_commit":"b6a4cf32253c5bc9a17295e7ab1b048243ee53bc","revision_root":"sha256:eeba7c3f875f002d11f14d454321e3c0d451beac258640f6aa84dca034b61788","proposal_status":"accepted","repository_root":"sha256:f231a54f1a82991a02685719158814d168e418fc2091ca299486fae13743901c","applied_exactly_as_reviewed":true},"nonclaims":["A proposed-state preview does not make a Decision or change Standing.","A satisfied protocol gate is permission for a human ruling, not acceptance.","The preview root is not a Repository root, Git commit, or projection release root."],"entry_root":"sha256:73c316dbe2379c92b8085fc6ee7619ddb24584d5ac8fec78540851ac761f8012","predictions":{"before_repository_root":"sha256:6da29efeedc34fb6e505c7546e894390418c807342940ecbf60cc025f99ddc1c","if_accept_repository_root":"sha256:f231a54f1a82991a02685719158814d168e418fc2091ca299486fae13743901c","if_reject_repository_root":"sha256:1ffe5b0cf7277aef42058b50ddb23bb3347ae67f459693f7885258956bd3f4d8"},"proposal_id":"vpr_2c3fe5888b00366a","preview_root":"sha256:88b078c6a15024d05be72207068e53c100b8b