INSERT INTO projection.reviews ("release_root", "repository_id", "proposal_id", "status", "kind", "target", "claim", "content_root", "receipt_root", "created_at", "reviewed_at", "reviewed_by", "decision_actor_class", "decision_session_ref", "decision_authority_principal_id", "decision_event_id", "decision_plan_root", "decision_provenance", "applied_event_id", "decision_reason", "decision_packet", "proposed_state_preview", "claim_retirement", "retired_by_claim_id", "row_root") VALUES ('sha256:6a07c7816760bed93a2c3815d67296dde6b9ff7bc5386fe61bb49c5e39aa2b70', '3d012325-3768-4b95-a385-c94e9f2a57a6', 'vpr_b5ca521d2a892eee', 'accepted', 'claim.revise', 'vcl_6763ba247d40303408a268b226c3e27d7a753b63fca3eb0de99619d509346bfb', 'At lean-proofs commit 423344341fbfdf4f8f684a302c5d05379125e7dc, Erdos94.variants.sum_multiplicity proves that for every finite planar point set P, the sum over its distinct determined distances of the unordered-pair distance multiplicities equals P.card.choose 2, matching Formal Conjectures commit 94a278e06a8bcbc2e4f2935e491c0c115ec832e0. For occurrence resolution only, the exact occurrence Erdos94.erdos_94.variants.sum_multiplicity is associated with problem:erdos:94 under resolver entity root sha256:32f6e98a826da23c12c7cfcb8853e4712de130136c59f0454bd115c3fdb1e6b1. That occurrence is one of four Erdős 94 declarations Formal Conjectures publishes, and this identity does not establish the cubic distance-multiplicity conjecture.', 'sha256:aaaf6ebbf510ad08e6376c5958d23f4eb7704944f7d37916eee4ae253e809b3b', 'sha256:2d10ba2ff1aff901aeb8d16993fee8933938345ae32fe3e458ad2a4a60ff1adf', '2026-08-18T18:38:01.000Z', '2026-08-18T18:46:11.000Z', 'agent:submission-v3-cleanup-decision', 'agent', 'codex:019fe903-28b7-73d1-bd26-bdd9a083c1a4', 'local:device-sha256:67fbb8e56377e6868e9f941524e0bf39cfb4fd2a4bfdd25c2edb93fc82f86213|uid:501', 'vev_1bb01953aec0d5ca', NULL, 'signed_record', 'vev_e04b25b2a4c02a15', 'Accept the byte-identical Erdős 94 assertion as the current Submission v3 revision after two scoped actor-separated fidelity reviews. This removes only the obsolete recovery caveat, preserves the exact occurrence mapping and every scientific limit, and adds no new validation.', NULL, '{"base":{"git_commit":"cd17762373ae4dd7be8a1dca6b934a895c4cd048","revision_root":"sha256:a952f962577d77b469cfb47e9629f124ce129ec7fccc33ed9227670d2e89ef20","repository_root":"sha256:c465145c974a09e8b535efc7e3b6e7755e8b73916d4bad3403c2a41c12841875"},"state":"terminal_historical","inputs":{"claim_root":"sha256:aaaf6ebbf510ad08e6376c5958d23f4eb7704944f7d37916eee4ae253e809b3b","proposal_root":"sha256:b5ca521d2a892eee2c156f25f6ef4849edab5b436e6855fd924a25d7427ac882","repository_root":"sha256:c465145c974a09e8b535efc7e3b6e7755e8b73916d4bad3403c2a41c12841875","submission_root":"sha256:2d10ba2ff1aff901aeb8d16993fee8933938345ae32fe3e458ad2a4a60ff1adf","verification_set_root":"sha256:4125e990f262e75f8fdfe97315e5c485cfa235ba9b284d611fb1905a653cf856"},"schema":"vela.projection-proposed-state-preview.v1","blocker":null,"terminal":{"git_commit":"c875b49a7b703d0c0bf6892c345ffd7153788534","revision_root":"sha256:32836f4433fae84e890bc31bb9b10bb20b8e9552998a09a9926f6cfe7c3d2e5f","proposal_status":"accepted","repository_root":"sha256:a956b84c437202e5a02cc9e036a621bd14a302b34a75758115730bdbb77c52a4","applied_exactly_as_reviewed":true},"nonclaims":["A proposed-state preview does not make a Decision or change Standing.","A satisfied protocol gate is permission for a human ruling, not acceptance.","The preview root is not a Repository root, Git commit, or projection release root."],"entry_root":"sha256:31ce44fc2aecef8adb7cacc1b29842ca84b43a0334873fb0f186de15fed887ef","predictions":{"before_repository_root":"sha256:c465145c974a09e8b535efc7e3b6e7755e8b73916d4bad3403c2a41c12841875","if_accept_repository_root":"sha256:a956b84c437202e5a02cc9e036a621bd14a302b34a75758115730bdbb77c52a4","if_reject_repository_root":"sha256:96446fcb447b914cb4c853a2c0b6e2f64444a96ece75a0ccfa4d944b8f