en its pinned Mathlib and lean-proofs.","No external source-owner review, human review, upstream acceptance, or external adoption occurred.","Producer checks are not Verification, Decision, or Standing."],"identity":{"schema":"vela.signer-identity.v1","actor_id":"agent:submission-v3-cleanup","actor_class":"agent","declared_at":"2026-08-18T18:37:55Z","public_key_hex":"804d1d3188c5965f9911248193ccb903e29f6b19e642dbdb6d206fe48b5e9de5"},"artifacts":[{"kind":"source-evidence","path":"evidence/current/erdos-94/pilot-input.v1.json","digest":"sha256:e2054e7d5d57d1d1f4fd311d26dba65afb90ef873e7f04cb7bb5e431e43148eb"},{"kind":"producer-report","path":"evidence/current/erdos-94/producer-report.v1.json","digest":"sha256:119e4d22c1e8e5f2931f576e6e1af92f906f7bd49d7f4de28b22cb92955600ad"},{"kind":"occurrence-binding","path":"evidence/current/erdos-94/occurrence-binding.v2.json","digest":"sha256:06498cbc38514b7995a07e8c3a95901a8fb19763e44c6b9c97f28973104dfca1"}],"provenance":{"producer":"agent:submission-v3-cleanup","emitted_at":"2026-08-18T18:37:55Z","source_system":"vela-cli"},"replayability":"exact","producer_checks":[{"method":"lean-build","outcome":"pass","authority":"producer_reported"},{"method":"axiom-audit","outcome":"pass","authority":"producer_reported"}],"requested_change":{"kind":"correct_claim","target":{"claim_id":"vcl_4cae0d412a95d1965b927e1f7dbaa4245f5b9c3f84c5913e1d6a7880d6349165","claim_root":"sha256:aedff5078a30bea1f8a51c1188f2f0aa9bc43da06c894706297d8bd7a4830767"}},"verification_requirements":["submission_v3_revision_fidelity","scientific_meaning_and_state_fidelity"]}'::jsonb, 'sha256:638062ee25cc9aa8acd5814e5ee68459138edc278cc3e8f512cc131bda345745');
