INSERT INTO projection.graph_nodes ("release_root", "repository_id", "node_id", "kind", "label", "plane", "trust", "standing", "href", "x", "y", "content", "row_root") VALUES ('sha256:6a07c7816760bed93a2c3815d67296dde6b9ff7bc5386fe61bb49c5e39aa2b70', '3d012325-3768-4b95-a385-c94e9f2a57a6', 'vcl_1da4282b752192c52c2a985476fc13bfe460da01e4fe26c5543b7acb37d8b120', 'claim', 'The Lean development starfleet/erdos-321 establishes a two-sided asymptotic bound on extremalSize, which denotes the same quantity as Formal Conjectures'' Erdos321.R at pages commit 59f30aa3, and which therefore supplies a candidate answer for erdos_321.variants.isTheta rather than a proof of it.', 'scientific_state', 'pending', 'superseded', '/repositories/math/claims/vcl_1da4282b752192c52c2a985476fc13bfe460da01e4fe26c5543b7acb37d8b120', -3.03628, -8.036247, '{"id":"vcl_1da4282b752192c52c2a985476fc13bfe460da01e4fe26c5543b7acb37d8b120","kind":"claim","label":"The Lean development starfleet/erdos-321 establishes a two-sided asymptotic bound on extremalSize, which denotes the same quantity as Formal Conjectures'' Erdos321.R at pages commit 59f30aa3, and which therefore supplies a candidate answer for erdos_321.variants.isTheta rather than a proof of it.","plane":"scientific_state","trust":"pending","standing":"superseded","claim_root":"sha256:470072c1a598409aa8d27e420de7e24ea66dce94cf5fb3fcb97d9578d8991c63","source_title":"Authenticated Submission vsb_6cc500cc8153c8f5","assertion_kind":"theoretical"}'::jsonb, 'sha256:e7e9a7def2dca4edd27adf8af4f174bdc67dcd4ed5c1ec6c839053eda43f2d3b');
INSERT INTO projection.graph_nodes ("release_root", "repository_id", "node_id", "kind", "label", "plane", "trust", "standing", "href", "x", "y", "content", "row_root") VALUES ('sha256:6a07c7816760bed93a2c3815d67296dde6b9ff7bc5386fe61bb49c5e39aa2b70', '3d012325-3768-4b95-a385-c94e9f2a57a6', 'vcl_4cae0d412a95d1965b927e1f7dbaa4245f5b9c3f84c5913e1d6a7880d6349165', 'claim', 'At lean-proofs commit 423344341fbfdf4f8f684a302c5d05379125e7dc, Erdos94.variants.sum_multiplicity proves that for every finite planar point set P, the sum over its distinct determined distances of the unordered-pair distance multiplicities equals P.card.choose 2, matching Formal Conjectures commit 94a278e06a8bcbc2e4f2935e491c0c115ec832e0. For occurrence resolution only, the exact occurrence Erdos94.erdos_94.variants.sum_multiplicity is associated with problem:erdos:94 under resolver entity root sha256:32f6e98a826da23c12c7cfcb8853e4712de130136c59f0454bd115c3fdb1e6b1. That occurrence is one of four Erdős 94 declarations Formal Conjectures publishes, and this identity does not establish the cubic distance-multiplicity conjecture.', 'scientific_state', 'pending', 'superseded', '/repositories/math/claims/vcl_4cae0d412a95d1965b927e1f7dbaa4245f5b9c3f84c5913e1d6a7880d6349165', -0.716846, 3.043756, '{"id":"vcl_4cae0d412a95d1965b927e1f7dbaa4245f5b9c3f84c5913e1d6a7880d6349165","kind":"claim","label":"At lean-proofs commit 423344341fbfdf4f8f684a302c5d05379125e7dc, Erdos94.variants.sum_multiplicity proves that for every finite planar point set P, the sum over its distinct determined distances of the unordered-pair distance multiplicities equals P.card.choose 2, matching Formal Conjectures commit 94a278e06a8bcbc2e4f2935e491c0c115ec832e0. For occurrence resolution only, the exact occurrence Erdos94.erdos_94.variants.sum_multiplicity is associated with problem:erdos:94 under resolver entity root sha256:32f6e98a826da23c12c7cfcb8853e4712de130136c59f0454bd115c3fdb1e6b1. That occurrence is one of four Erdős 94 declarations Formal Conjectures publishes, and this identity does not establish the cubic distance-multiplicity conjecture.","plane":"scientific_state","trust":"pending","standing":"superseded","claim_root":"sha256:aedff5078a30bea1f8a51c1188f2f0aa9bc43da06c894706297d8bd7a4830767","source_title":"Authenticated Submission vsb_d49869f07a7907d4","assertion_kind":"theoretical"}'::jsonb, 'sha256:3eb3d228d27e216ca24663a342a28c39514241d7d012b3d1bd27e46371fe0d0e');
