INSERT INTO projection.search_documents ("release_root", "repository_id", "kind", "document_id", "assertion", "source_title", "standing", "href", "row_root") VALUES ('sha256:53a7cedcf0df635437ff442498c15801b09399f6cc4441dc041d725bcb318476', '3d012325-3768-4b95-a385-c94e9f2a57a6', 'claim', 'vcl_4cae0d412a95d1965b927e1f7dbaa4245f5b9c3f84c5913e1d6a7880d6349165', 'At lean-proofs commit 423344341fbfdf4f8f684a302c5d05379125e7dc, Erdos94.variants.sum_multiplicity proves that for every finite planar point set P, the sum over its distinct determined distances of the unordered-pair distance multiplicities equals P.card.choose 2, matching Formal Conjectures commit 94a278e06a8bcbc2e4f2935e491c0c115ec832e0. For occurrence resolution only, the exact occurrence Erdos94.erdos_94.variants.sum_multiplicity is associated with problem:erdos:94 under resolver entity root sha256:32f6e98a826da23c12c7cfcb8853e4712de130136c59f0454bd115c3fdb1e6b1. That occurrence is one of four Erdős 94 declarations Formal Conjectures publishes, and this identity does not establish the cubic distance-multiplicity conjecture.', 'Authenticated Submission vsb_d49869f07a7907d4', 'superseded', '/repositories/math/claims/vcl_4cae0d412a95d1965b927e1f7dbaa4245f5b9c3f84c5913e1d6a7880d6349165', 'sha256:94990d4a6c3d47cfea75c9ebce4eacd5f3c549d17c0774146af4517b833a8e85');
