INSERT INTO projection.source_declarations ("declaration_root", "source_id", "native_namespace", "publisher_or_maintainer", "locators", "attributed_claims", "source_kind", "rights", "snapshot_policy", "adapter", "coverage", "row_root") VALUES ('sha256:0b156480f46fc1e84218fce8f7e96f34a3660111c8c12bedf1c0da8b5ce67963', 'source:palomar-registry', 'palomar-registry', 'Palomar Registry', '[{"url":"https://palomar-registry.org/","kind":"homepage","locator_id":"homepage"},{"url":"https://data.palomar-registry.org/recent.json","kind":"api","locator_id":"recent-feed"},{"url":"https://data.palomar-registry.org/entries/PALOMAR-2026-08-19-000002-v1.json","kind":"artifact","locator_id":"entry"},{"url":"https://github.com/PalomarRegistry/PalomarPolicy","kind":"git","locator_id":"review-policy"},{"url":"https://palomar-registry.org/about","kind":"documentation","locator_id":"rights"}]'::jsonb, '[{"name":"Palomar Registry","role":"publisher","basis_locator_id":"homepage"}]'::jsonb, 'formal_library', '{"basis":"Registry metadata is published under CC0, stated on the registry''s about page; each record additionally carries the source project''s own license identity and license-file digest, which this declaration attributes and does not assert.","access":"public","status":"declared","redistribution":"full_under_license","license_expression":"CC0-1.0"}'::jsonb, '{"mode":"retained_exact_bytes","reason":"Palomar publishes no digest or signature over the entry JSON and may re-render older entries to the current schema, so the adapter pins its own consumer-computed root over the exact fetched entry bytes and re-verifies both evidence reports against the digests inside the entry.","retention":"immutable_artifact"}'::jsonb, '{"mode":"networked_acquisition","version":"1.0.0","adapter_id":"problems-data/palomar-registry","adapter_root":"sha256:753f8e0579c8df2b00b3252be6e7903828e452f958f62a68c8efc96edfc4cdcb","acquisition_contract":"vela.source-adapter-bundle.v2","observation_contract":"vela.math-source-observation.v1"}'::jsonb, '{"included":["The one registered entry PALOMAR-2026-08-19-000002 v1 (elliotglazer/erdos501, an independence resolution of Erdős problem #501), as exact retained entry bytes","Exact record identity, source commit, formalization surface, verification-run identity, review policy pin and digests, bounded review warnings, preservation locators, and Palomar-local status as the entry declares them"],"omissions":[{"code":"palomar_status_is_external_standing","description":"Palomar''s registered status and trust level are Palomar-local external standing; they create no Vela Standing, Verification, acceptance, or admission."},{"code":"palomar_nonclaims_are_registry_level","description":"Palomar claims no novelty, no quality assessment, no peer review, no publication status, and no informal-proof verification; these attributed nonclaims are registry-level prose, not per-record data."},{"code":"palomar_mechanical_pass_is_one_scoped_check","description":"Comparator, Lean-kernel, and NanoDa results are folded into Palomar''s single mechanical pass and retained as one scoped external check (palomar-mechanical); Vela re-derives none of them and none is a Vela Verification."},{"code":"palomar_review_is_llm_under_policy","description":"The semantic review is an LLM review under a pinned policy commit; its outcome and bounded findings are attributed observations, never adjudication."},{"code":"palomar_consent_is_asserted_relationship","description":"The submitter relationship is an asserted field; Palomar publishes no signed consent artifact."},{"code":"palomar_admission_process_unobservable","description":"Only the admission outcome — status registered with its timestamps — is observable; the registry''s admission decision process is internal."},{"code":"palomar_version_relation_reconstructed","description":"Version relations are reconstructed from the shared registry ID and integer versions; Palomar publishes no supersedes or corrects field, and the reason for a new version is unobservable."},{"code":"palomar_entry_bytes_not_provider_signed","description":"Palomar publishes no digest or signature over the entry JSON; authenticity rests on TLS retrieval plus the consumer-computed retained-bytes root, and version-URL immutability is Palomar''s assertion."},{"code":"palomar_challenge_render_not_archived","description":"The challenge render is retained as a locator and provider tree digest only; its bytes are not archived."},{"code":"palomar_evidence_tree_not_archived","description":"Beyond the two digest-verified reports, the evidence tree — comparator log tail, resource usage, Mathlib cache and the rest — is pinned by evidence_tree_sha256 and not archived."}],"repository_slugs":["math"]}'::jsonb, 'sha256:0b156480f46fc1e84218fce8f7e96f34a3660111c8c12bedf1c0da8b5ce67963');
