INSERT INTO projection.source_observations ("observation_root", "source_id", "observation_id", "declaration_root", "acquisition_root", "observed_at", "native_revision", "snapshot_root", "snapshot_state", "projected_record_count", "projected_records_root", "coverage", "omissions", "row_root") VALUES ('sha256:00ff7a0f84c0a37d721f1707053680ebc65dcaac6670fd6f77901e49de3db24e', 'source:palomar-registry', 'observation:palomar-registry:d5994e671a0ec7cc', 'sha256:0b156480f46fc1e84218fce8f7e96f34a3660111c8c12bedf1c0da8b5ce67963', 'sha256:d5994e671a0ec7cc9bf676e7188f01eaf7034d9995bbda3f7367c51120c3a6c0', '2026-08-19T14:25:37-04:00', '{"kind":"observation","tree":null,"value":"sha256:306220a43c9696396c9f0cbb87ddb3d3352941a4b411988269386911c2492688","content_root":"sha256:306220a43c9696396c9f0cbb87ddb3d3352941a4b411988269386911c2492688"}'::jsonb, 'sha256:306220a43c9696396c9f0cbb87ddb3d3352941a4b411988269386911c2492688', 'retained_exact_bytes', '1', 'sha256:d0f87c766291e0ee2876a13e784d5837b144c193c26a796bd4b1bff73591bf7f', '{"status":"complete","included":["The one exact Palomar registry entry served at the declared versioned entry URL, with its two evidence reports re-verified against the digests inside the entry."],"native_record_count":1,"projected_record_count":1}'::jsonb, '[{"code":"palomar_challenge_render_not_archived","description":"The challenge render is retained as a locator and provider tree digest only; its bytes are not archived."},{"code":"palomar_evidence_tree_not_archived","description":"Beyond the two digest-verified reports, the evidence tree — comparator log tail, resource usage, Mathlib cache and the rest — is pinned by evidence_tree_sha256 and not archived."},{"code":"palomar_mechanical_pass_is_one_scoped_check","description":"Comparator, Lean-kernel, and NanoDa results are folded into Palomar''s single mechanical pass and retained as one scoped external check (palomar-mechanical); Vela re-derives none of them and none is a Vela Verification."},{"code":"palomar_status_is_external_standing","description":"Palomar''s registered status and trust level are Palomar-local external standing; they create no Vela Standing, Verification, acceptance, or admission."},{"code":"palomar_nonclaims_are_registry_level","description":"Palomar claims no novelty, no quality assessment, no peer review, no publication status, and no informal-proof verification; these attributed nonclaims are registry-level prose, not per-record data."},{"code":"palomar_review_is_llm_under_policy","description":"The semantic review is an LLM review under a pinned policy commit; its outcome and bounded findings are attributed observations, never adjudication."},{"code":"palomar_consent_is_asserted_relationship","description":"The submitter relationship is an asserted field; Palomar publishes no signed consent artifact."},{"code":"palomar_admission_process_unobservable","description":"Only the admission outcome — status registered with its timestamps — is observable; the registry''s admission decision process is internal."},{"code":"palomar_version_relation_reconstructed","description":"Version relations are reconstructed from the shared registry ID and integer versions; Palomar publishes no supersedes or corrects field, and the reason for a new version is unobservable."},{"code":"palomar_entry_bytes_not_provider_signed","description":"Palomar publishes no digest or signature over the entry JSON; authenticity rests on TLS retrieval plus the consumer-computed retained-bytes root, and version-URL immutability is Palomar''s assertion."}]'::jsonb, 'sha256:00ff7a0f84c0a37d721f1707053680ebc65dcaac6670fd6f77901e49de3db24e');
