INSERT INTO projection.native_records ("observation_root", "source_id", "native_id", "native_kind", "native_revision", "title", "summary", "locators", "metadata", "metadata_root", "content_root", "availability", "row_root") VALUES ('sha256:6860725b904269a25b46d321291d89c9994ce950f439b7584ec16f8cbd626b68', 'source:formal-conjectures', 'Erdos321.erdos_321.variants.lower', 'formal_conjecture', '59f30aa314ba225fcd9268723ce8291616df1ab0', 'Erdos321.erdos_321.variants.lower', '∀ (N k : ℕ), 4 ≤ k → ↑k ≤ Real.log^[k] ↑N → ↑N / Real.log ↑N * ∏ i ∈ Finset.Icc 3 k, Real.log^[i] ↑N ≤ ↑(Erdos321.R N)', '[{"url":"https://github.com/google-deepmind/formal-conjectures/blob/59f30aa314ba225fcd9268723ce8291616df1ab0/FormalConjectures/ErdosProblems/321.lean","kind":"artifact","locator_id":"native-1"},{"url":"https://google-deepmind.github.io/src/FormalConjectures/ErdosProblems/%C2%AB321%C2%BB/","kind":"artifact","locator_id":"native-2"}]'::jsonb, '{"module":"FormalConjectures.ErdosProblems.«321»","subsets":"[]","category":"research solved","docstring":"Let $R(N)$ be the maximal such size. Results of Bleicher and Erdős from [BlEr75] and [BlEr76b] imply that\n$$\n\\frac{N}{\\log N} \\prod_{i=3}^{k} \\log_i N \\le R(N),\n$$\nvalid for any $k \\ge 4$ with $\\log_k N \\ge k$ and any $r \\ge 1$ with $\\log_{2r} N \\ge 1$. (In these bounds $\\log_i n$ denotes the $i$-fold iterated logarithm.)\n\n[BlEr75] Bleicher, M. N. and Erdős, P., _The number of distinct subsums of $\\sum \\sb{1}\\spN\\,1/i$_. Math. Comp. (1975), 29-42.\n[BlEr76b] Bleicher, Michael N. and Erdős, Paul, _Denominators of Egyptian fractions. II_. Illinois J. Math. (1976), 598-613.\n","collection":"Erdős Problems","answer_kinds":"[]","subject_codes":"[\"11\"]","subject_names":"[\"Number theory\"]","category_label":"Solved","collection_url":"https://www.erdosproblems.com","display_module":"FormalConjectures.ErdosProblems.321","file_first_added":"2025-10-06T19:01:30+09:00","formal_statement":"∀ (N k : ℕ), 4 ≤ k → ↑k ≤ Real.log^[k] ↑N → ↑N / Real.log ↑N * ∏ i ∈ Finset.Icc 3 k, Real.log^[i] ↑N ≤ ↑(Erdos321.R N)","source_blob_root":"sha256:601d8486743aede6803feaaefc7bbb73f0aa8873d0296a6a1c5400fd86c32357","formal_proof_kind":null,"file_last_modified":"2026-07-17T01:28:26+02:00","formal_proof_locator":null,"formal_proof_present":false,"formal_proof_sorry_free":false}'::jsonb, 'sha256:ec5f2d13be59bf820d79d1786c41586ed9a090c8acf4d7a0fcdf78bf017a2862', 'sha256:4db565f3dabda9e7e14f4b20a3bc4c4d9c82f1c615310ced4e921be1c5213c75', 'reference_only', 'sha256:0877d4a131d9df12df2ee34b8b4a2917da98b18eeec845694072c7785407febc');
