INSERT INTO projection.native_records ("observation_root", "source_id", "native_id", "native_kind", "native_revision", "title", "summary", "locators", "metadata", "metadata_root", "content_root", "availability", "row_root") VALUES ('sha256:53a056daf51571653d51b00b6c7e4b6e7b1d42af3fc6a3edd48bae859c213826', 'source:formal-conjectures', 'Erdos203.erdos_203', 'formal_conjecture', '59f30aa314ba225fcd9268723ce8291616df1ab0', 'Erdos203.erdos_203', 'True ↔ ∃ m, m.Coprime 6 ∧ ∀ (k l : ℕ), ¬Nat.Prime (2 ^ k * 3 ^ l * m + 1)', '[{"url":"https://github.com/google-deepmind/formal-conjectures/blob/59f30aa314ba225fcd9268723ce8291616df1ab0/FormalConjectures/ErdosProblems/203.lean","kind":"artifact","locator_id":"native-1"},{"url":"https://google-deepmind.github.io/src/FormalConjectures/ErdosProblems/%C2%AB203%C2%BB/","kind":"artifact","locator_id":"native-2"}]'::jsonb, '{"module":"FormalConjectures.ErdosProblems.«203»","subsets":"[]","category":"research open","docstring":"Is there an integer $m$ with $(m, 6) = 1$ such that none of $2^k \\cdot 3^\\ell \\cdot m + 1$ are prime,\nfor any $k, \\ell \\ge 0$?\n","collection":"Erdős Problems","answer_kinds":"[]","subject_codes":"[\"5\"]","subject_names":"[\"Combinatorics\"]","category_label":"Open","collection_url":"https://www.erdosproblems.com","display_module":"FormalConjectures.ErdosProblems.203","file_first_added":"2025-02-13T11:10:46+01:00","formal_statement":"True ↔ ∃ m, m.Coprime 6 ∧ ∀ (k l : ℕ), ¬Nat.Prime (2 ^ k * 3 ^ l * m + 1)","source_blob_root":"sha256:dfd0eb1bf073a27ad74a398acb7c2986b73be9cf72e6dc6ed9fc4618c6538cfb","formal_proof_kind":null,"file_last_modified":"2026-07-17T01:28:26+02:00","formal_proof_locator":null,"formal_proof_present":false,"formal_proof_sorry_free":false}'::jsonb, 'sha256:1622cde3edddadbcb2f44715a070f608b75be961d06400df27cf9991dc46c085', 'sha256:991e027005b1b8f6227b03fc431e35007094503049cd4b72a621bef6c4ae9535', 'reference_only', 'sha256:3046c183a33e16b788e2a977eb9f0d6c2328fe5c216b62320d0d437054303277');
INSERT INTO projection.native_records ("observation_root", "source_id", "native_id", "native_kind", "native_revision", "title", "summary", "locators", "metadata", "metadata_root", "content_root", "availability", "row_root") VALUES ('sha256:a10796d13044ef5f9700b43b804c4c7ed4f326ad1bd8e204933baa3b53517f2e', 'source:formal-conjectures', 'Erdos521.erdos_521', 'formal_conjecture', '59f30aa314ba225fcd9268723ce8291616df1ab0', 'Erdos521.erdos_521', 'False ↔ Erdos521.Claim', '[{"url":"https://github.com/google-deepmind/formal-conjectures/blob/59f30aa314ba225fcd9268723ce8291616df1ab0/FormalConjectures/ErdosProblems/521.lean","kind":"artifact","locator_id":"native-1"},{"url":"https://google-deepmind.github.io/src/FormalConjectures/ErdosProblems/%C2%AB521%C2%BB/","kind":"artifact","locator_id":"native-2"}]'::jsonb, '{"module":"FormalConjectures.ErdosProblems.«521»","subsets":"[]","category":"research solved","docstring":"Let $(\\epsilon_k)_{k\\geq 0}$ be independently uniformly chosen at random from\n$\\{-1,1\\}$. If $R_n$ counts the number of real roots of\n$f_n(z)=\\sum_{0\\leq k\\leq n}\\epsilon_k z^k$ then is it true that, almost surely,\n$$\\lim_{n\\to \\infty}\\frac{R_n}{\\log n}=\\frac{2}{\\pi}?$$\n\nThe answer is no: this almost-sure limit fails. This result was obtained first by others, who\ndeserve the credit for the problem; the link is to an independent machine-checked proof by\nStar Fleet Math.\n","collection":"Erdős Problems","answer_kinds":"[\"Prop\"]","subject_codes":"[\"11\",\"60\"]","subject_names":"[\"Number theory\",\"Probability theory and stochastic processes\"]","category_label":"Solved","collection_url":"https://www.erdosproblems.com","display_module":"FormalConjectures.ErdosProblems.521","file_first_added":"2026-08-07T07:51:36-04:00","formal_statement":"False ↔ Erdos521.Claim","source_blob_root":"sha256:d165750c9a5168f432f945f57cc9e58daf4d656e489c79c9744e55aec422b9e3","formal_proof_kind":"lean4","file_last_modified":"2026-08-07T07:51:36-04:00","formal_p