INSERT INTO projection.native_records ("observation_root", "source_id", "native_id", "native_kind", "native_revision", "title", "summary", "locators", "metadata", "metadata_root", "content_root", "availability", "row_root") VALUES ('sha256:a10796d13044ef5f9700b43b804c4c7ed4f326ad1bd8e204933baa3b53517f2e', 'source:formal-conjectures', 'Erdos264.erdos_264.parts.i', 'formal_conjecture', '59f30aa314ba225fcd9268723ce8291616df1ab0', 'Erdos264.erdos_264.parts.i', '¬Erdos264.IsIrrationalitySequence fun x => 2 ^ x', '[{"url":"https://github.com/google-deepmind/formal-conjectures/blob/59f30aa314ba225fcd9268723ce8291616df1ab0/FormalConjectures/ErdosProblems/264.lean","kind":"artifact","locator_id":"native-1"},{"url":"https://google-deepmind.github.io/src/FormalConjectures/ErdosProblems/%C2%AB264%C2%BB/","kind":"artifact","locator_id":"native-2"}]'::jsonb, '{"module":"FormalConjectures.ErdosProblems.«264»","subsets":"[]","category":"research solved","docstring":"Is $2^n$ an example of an irrationality sequence? Kovač and Tao proved that it is not [KoTa24]\n\n[KoTa24] Kovač, V. and Tao T., On several irrationality problems for Ahmes series. arXiv:2406.17593 (2024).\n","collection":"Erdős Problems","answer_kinds":"[]","subject_codes":"[\"11\"]","subject_names":"[\"Number theory\"]","category_label":"Solved","collection_url":"https://www.erdosproblems.com","display_module":"FormalConjectures.ErdosProblems.264","file_first_added":"2025-08-29T16:11:49+01:00","formal_statement":"¬Erdos264.IsIrrationalitySequence fun x => 2 ^ x","source_blob_root":"sha256:c59caaa2524e3edd52944e63f5d9bb0614f1bc36d7fb8a0fec7029c14c266b46","formal_proof_kind":null,"file_last_modified":"2026-07-17T01:28:26+02:00","formal_proof_locator":null,"formal_proof_present":false,"formal_proof_sorry_free":false}'::jsonb, 'sha256:7ca6a4d68e93ec1e96077bb6d7bd8b2c5438b0aa33bb581e0cd9569d72ae323f', 'sha256:8e98f3952077ba0d3d65ca0b60a05e4b1a8da826b191042c8911721b4012cad8', 'reference_only', 'sha256:ee1a709587d4b9b2eba930