INSERT INTO projection.native_records ("observation_root", "source_id", "native_id", "native_kind", "native_revision", "title", "summary", "locators", "metadata", "metadata_root", "content_root", "availability", "row_root") VALUES ('sha256:a10796d13044ef5f9700b43b804c4c7ed4f326ad1bd8e204933baa3b53517f2e', 'source:formal-conjectures', 'Erdos1.erdos_1.variants.real', 'formal_conjecture', '59f30aa314ba225fcd9268723ce8291616df1ab0', 'Erdos1.erdos_1.variants.real', '∃ C > 0, ∀ (N : ℕ) (A : Finset ℝ), Erdos1.IsSumDistinctRealSet A N → N ≠ 0 → C * 2 ^ A.card < ↑N', '[{"url":"https://github.com/google-deepmind/formal-conjectures/blob/59f30aa314ba225fcd9268723ce8291616df1ab0/FormalConjectures/ErdosProblems/1.lean","kind":"artifact","locator_id":"native-1"},{"url":"https://google-deepmind.github.io/src/FormalConjectures/ErdosProblems/%C2%AB1%C2%BB/","kind":"artifact","locator_id":"native-2"}]'::jsonb, '{"module":"FormalConjectures.ErdosProblems.«1»","subsets":"[]","category":"research open","docstring":"A generalisation of the problem to sets $A \\subseteq (0, N]$ of real numbers, such that the subset\nsums all differ by at least $1$ is proposed in [Er73] and [ErGr80].\n\n[Er73] Erdős, P., _Problems and results on combinatorial number theory_. A survey of combinatorial theory (Proc. Internat. Sympos., Colorado State Univ., Fort Collins, Colo., 1971) (1973), 117-138.\n\n[ErGr80] Erdős, P. and Graham, R., _Old and new problems and results in combinatorial number theory_. Monographies de L''Enseignement Mathematique (1980).\n","collection":"Erdős Problems","answer_kinds":"[]","subject_codes":"[\"5\",\"11\"]","subject_names":"[\"Combinatorics\",\"Number theory\"]","category_label":"Open","collection_url":"https://www.erdosproblems.com","display_module":"FormalConjectures.ErdosProblems.1","file_first_added":"2025-02-13T11:10:46+01:00","formal_statement":"∃ C > 0, ∀ (N : ℕ) (A : Finset ℝ), Erdos1.IsSumDistinctRealSet A N → N ≠ 0 → C * 2 ^ A.card < ↑N","source_blob_root":"sha256:6754c87ff3e02086075f6911afbe771875ae1967f15c41f1f8882fe207da6cf0","formal_proof_kind":null,"file_last_modified":"2026-08-02T16:46:11+02:00","formal_proof_locator":null,"formal_proof_present":false,"formal_proof_sorry_free":false}'::jsonb, 'sha256:a00dc0fe701baf52afa2585952321fea7a98cd0c9cb435c2bd39c4adea286a43', 'sha256:b727e319c3b20be89beaffb81e63b06716d002a6f462c74913cdcf70333f366d', 'reference_only', 'sha256:f032b016bb7bcea26d84e9f4579c3ec37c3b7a297a1f33865c8253729aa96933');
